{
  "items": [
    {
      "name": "Finset.inf'_le",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SemilatticeInf α] {s : Finset β} (f : β → α) {b : β} (h : b ∈ s),\n  s.inf' ⋯ f ≤ f b"
    },
    {
      "name": "Real.le_sInf",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ} {a : ℝ}, (∀ x ∈ s, a ≤ x) → a ≤ 0 → a ≤ sInf s"
    },
    {
      "name": "Finset.le_inf'",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SemilatticeInf α] {s : Finset β} (H : s.Nonempty) (f : β → α) {a : α},\n  (∀ b ∈ s, a ≤ f b) → a ≤ s.inf' H f"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {w : σ → M},\n  (∀ (s : σ), 0 ≤ w s) → ∀ {s : σ} {f : σ →₀ ℕ}, f s ≠ 0 → w s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "le_csInf_iff",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLattice α] {s : Set α} {a : α},\n  BddBelow s → s.Nonempty → (a ≤ sInf s ↔ ∀ b ∈ s, a ≤ b)"
    },
    {
      "name": "Set.Nonempty.csInf_mem",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Finset",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : ConditionallyCompleteLinearOrder α] {s : Set α}, s.Nonempty → s.Finite → sInf s ∈ s"
    }
  ]
}
